  const activeId=scenarioActiveTab(kind,scenarioKey,items,{identity,matches}),tabs=items.map((item,index)=>{const id=String(identity(item)??""),text=String(label(item,index)||""),active=matches(id,activeId),editable=active&&editAction&&item.status!=="Removed";return `<span role="none" class="frame-section-tab-item ${active?"is-active":""}"><button type="button" role="tab" class="frame-section-tab ${active?"is-active":""}" data-scenario-tab-kind="${esc(kind)}" data-scenario-tab-id="${esc(id)}" data-scenario-tab-scenario="${esc(scenarioKey)}" aria-selected="${active}" tabindex="${active?0:-1}"><strong>${esc(text)}</strong></button>${editable?editAction(item,text):""}</span>`}).join("");
